<style>
    .returns-page{background:#f4f6f8;margin:-1.5rem;padding:24px;min-height:100vh;color:#4e565f;font-size:13px;letter-spacing:0}
    .returns-page a{color:#0068bd;text-decoration:none}.returns-page a:hover{text-decoration:underline}
    .returns-header{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:64px;padding:0 20px 8px;border-bottom:1px solid #dfe3e8}
    .returns-heading{display:flex;align-items:baseline;gap:26px;flex-wrap:wrap;min-width:0}.returns-heading h1,.returns-heading .customer{font-size:20px;font-weight:300;margin:0;color:#4e565f}
    .returns-heading h1{display:flex;align-items:center;gap:12px}.returns-heading .bi-star{font-size:20px}
