    .returns-body{padding:10px 12px 16px}.returns-fields{display:grid;grid-template-columns:minmax(100px,39%) minmax(0,1fr);gap:0 12px;line-height:18.5px}.returns-fields dt{font-weight:400;margin:0}.returns-fields dd{margin:0;min-width:0;overflow-wrap:anywhere}
