    .returns-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:16px 0}.returns-toolbar h1{font-size:20px;font-weight:400;margin:0}.returns-toolbar .btn,.returns-filters .btn{font-size:13px;border-radius:20px}
    .returns-filters{margin:0 0 16px;padding:12px;background:#fff;border:1px solid #dce1e7;border-radius:4px}.returns-filter-grid{display:grid;grid-template-columns:2fr repeat(4,minmax(110px,1fr));gap:12px;align-items:end}.returns-filters label{font-size:12px;margin-bottom:5px}.returns-filters .form-control,.returns-filters .form-select{font-size:13px;min-width:0}
